python -c 'import csv, numpy as np, spglib; from pymatgen.core import Structure; rows=list(csv.DictReader(open("nlo_pool.csv"))); print("N",len(rows)); print("ID formula reduced SG pointgroup volume_per_atom");
for r in rows:
 s=Structure.from_str(r["poscar"],fmt="poscar"); d=spglib.get_symmetry_dataset((s.lattice.matrix,s.frac_coords,s.atomic_numbers),symprec=0.01); print(r["candidate_id"],r["formula"],s.composition.reduced_formula,d.international,d.number,d.pointgroup,round(s.volume/len(s),2))'

python -c 'import csv,numpy as np; from pymatgen.core import Structure; rows=list(csv.DictReader(open("nlo_pool.csv"))); ids=set(range(1,5))|set(range(8,20))|set(range(31,37))|set(range(94,100))|{5,6,20,21,46,48,50,51,52,56,57,67,71,75,76,77,78,81,82,88,92,93};
for idx,r in enumerate(rows,1):
 if idx not in ids: continue
 s=Structure.from_str(r["poscar"],fmt="poscar"); out=[]
 for elem in s.composition.elements:
  if elem.symbol in ["Se","S","Cl","Li","K","Rb","Ba"]:continue
  tens=np.zeros((3,3,3)); norms=0; cn=[]; bonds=[]; lmax=[]
  for i,site in enumerate(s):
   if site.specie!=elem:continue
   ns=sorted([n for n in s.get_neighbors(site,4.5) if n.specie.symbol in ["Se","S","Cl"]],key=lambda n:n.nn_distance); ds=np.array([n.nn_distance for n in ns]); cut=min(ds[0]*1.2,ds[3]*1.07) if len(ds)>3 else ds[0]*1.2; nn=[n for n in ns if n.nn_distance<=cut]; cn.append(len(nn)); bonds.extend([n.nn_distance for n in nn]); T=np.zeros((3,3,3))
   for n in nn:
    u=(n.coords-site.coords)/n.nn_distance; T+=np.einsum("i,j,k->ijk",u,u,u)
   tens+=T; norms+=np.linalg.norm(T); lmax.append(np.max(np.abs(T)))
  out.append("%s CN%s r%.2f maxT/V %.5f coh%.2f idx%s"%(elem.symbol,str(cn),np.mean(bonds),np.max(np.abs(tens))/s.volume,np.linalg.norm(tens)/norms if norms>1e-8 else 0,str(np.unravel_index(np.argmax(abs(tens)),tens.shape))))
 print(r["candidate_id"],s.composition.reduced_formula,"V=%.1f"%s.volume,"; ".join(out))'

