python -c 'import csv,numpy as np; from pymatgen.core import Structure; rows=list(csv.DictReader(open("nlo_pool.csv"))); weights={"Ga":2100.,"Zn":1800.,"Mg":250.,"Li":100.}; ids=set(range(1,5))|set(range(8,20))|set(range(31,37))|set(range(94,100));
for idx,r in enumerate(rows,1):
 if idx not in ids:continue
 s=Structure.from_str(r["poscar"],fmt="poscar"); terms={}
 for elem in s.composition.elements:
  if elem.symbol not in weights:continue
  T=np.zeros((3,3,3))
  for site in s:
   if site.specie!=elem:continue
   ns=sorted([n for n in s.get_neighbors(site,4.5) if n.specie.symbol=="Se"],key=lambda n:n.nn_distance);cut=min(ns[0].nn_distance*1.2,ns[3].nn_distance*1.07)
   for n in ns:
    if n.nn_distance>cut:continue
    u=(n.coords-site.coords)/n.nn_distance; T+=np.einsum("i,j,k->ijk",u,u,u)
  terms[elem.symbol]=T/s.volume*weights[elem.symbol]
 D=sum(terms.values()); k=np.unravel_index(np.argmax(abs(D)),D.shape);print(r["candidate_id"],"heuristic=%.2f"%np.max(abs(D)),"component",k,"terms",{e:round(T[k],2) for e,T in terms.items()})'

