 s=Structure.from_str(r["poscar"],fmt="poscar");cell=(s.lattice.matrix,s.frac_coords,s.atomic_numbers); ds=[spglib.get_symmetry_dataset(cell,symprec=t) for t in [0.001,0.01,0.05,0.1]]; sg=[str(d.number)+":"+d.international for d in ds];
