  terms[e.symbol]=T/s.volume
 D=sum(terms.values());idx=np.unravel_index(np.argmax(abs(D)),D.shape); print(r["candidate_id"],s.composition.reduced_formula,"heuristic %.2f"%np.max(abs(D)),"terms",{e:round(T[idx],2) for e,T in terms.items()},"component",idx)'

